Spatial Thinning to Reduce Sampling Bias

# Thin to one record per ~5 km grid cell
thin_grid &lt;- function(pts, cell_km = 5) {
  pts |&gt;
    st_transform(2100) |&gt;
    mutate(cell = paste(
      floor(st_coordinates(geometry)[, 1] / (cell_km * 1000)),
      floor(st_coordinates(geometry)[, 2] / (cell_km * 1000)))) |&gt;
    group_by(cell) |&gt;
    slice(1) |&gt;
    ungroup() |&gt;
    st_transform(4326)
}

pts_thin &lt;- thin_grid(pts, cell_km = 5)

Gridded β-Diversity in R

# Build a 0.5° grid
grid &lt;- st_make_grid(greece, cellsize = 0.5, square = TRUE) |&gt;
        st_as_sf() |&gt;
        mutate(cell_id = row_number())

# Join occurrences to grid
sp_grid &lt;- st_join(all_species_pts, grid)

# Site × species matrix
mat &lt;- sp_grid |&gt;
  st_drop_geometry() |&gt;
  count(cell_id, species) |&gt;
  pivot_wider(names_from = species, values_from = n,
              values_fill = 0) |&gt;
  column_to_rownames("cell_id")

# Presence/absence + Simpson dissimilarity
pa  &lt;- ifelse(mat &gt; 0, 1, 0)
dis &lt;- beta.pair(pa)$beta.sim
hc  &lt;- hclust(dis, method = "average")
clusters &lt;- cutree(hc, k = 5)
